void notConnectedScreen(void)
{
    u8g2.clearBuffer();
    u8g2.setFontMode(1);
    u8g2.setBitmapMode(1);
    // Layer 1
    u8g2.setFont(u8g2_font_haxrcorp4089_tr);
    u8g2.drawStr(25, 24, "> Not Connected <");

    // download
    u8g2.drawXBMP(55, 30, 14, 16, noBluetooth);

    u8g2.sendBuffer();
    delay(1000);
}

int currentAppIndex = 0;

void nextApp()
{
    currentAppIndex = (currentAppIndex + 1) % totalApps;
}

void previousApp()
{
    currentAppIndex = (currentAppIndex - 1 + totalApps) % totalApps;
}

void PC_Control(void)
{
    u8g2.clearBuffer();
    u8g2.setFontMode(1);
    u8g2.setBitmapMode(1);
    int connected = bleKeyboard.isConnected();
    if (connected)
    {
        u8g2.setDrawColor(1);
        u8g2.drawXBMP(118, 2, 5, 8, image_Bluetooth_bits);
    }
    if (rightButtonTap())
    {
        if (!connected)
        {
            Serial.println("BLE Not Connected");
            notConnectedScreen();
            return;
        }
        u8g2.clearBuffer();
        u8g2.setFontMode(1);
        u8g2.setBitmapMode(1);
        // download
        u8g2.drawXBMP(57, 21, 15, 16, sendingBits);

        // Layer 2
        u8g2.setFont(u8g2_font_4x6_tr);
        u8g2.drawStr(35, 47, "Sending Command");

        u8g2.sendBuffer();
        bleKeyboard.press(KEY_LEFT_ALT);
        bleKeyboard.press(KEY_BACKSPACE);
        delay(100);
        playBuzzer(false);
        bleKeyboard.releaseAll();
        delay(500);
        bleKeyboard.print(AppNames[currentAppIndex][1]);
        delay(500);
        bleKeyboard.write(KEY_RETURN);
        Serial.println("BLE Command Sent");
        delay(1000);
    }
    if (leftButtonTap())
    {
        if (!connected)
        {
            Serial.println("BLE Not Connected");
            notConnectedScreen();
            return;
        }
        u8g2.clearBuffer();
        u8g2.setFontMode(1);
        u8g2.setBitmapMode(1);
        // download
        u8g2.drawXBMP(57, 21, 15, 16, sendingBits);
        
        // Layer 2
        u8g2.setFont(u8g2_font_4x6_tr);
        u8g2.drawStr(35, 47, "Sending Command");
        
        u8g2.sendBuffer();
        bleKeyboard.press(KEY_LEFT_ALT);
        bleKeyboard.press(KEY_F4);
        delay(10);
        bleKeyboard.releaseAll();
        return;
    }
    static unsigned long lastScroll = millis();
    if (downButtonHold() && (millis() - lastScroll > 200))
    {
        nextApp();
        lastScroll = millis();
    }

    if (upButtonHold() && (millis() - lastScroll > 200))
    {
        previousApp();
        lastScroll = millis();
    }
    // Layer 1
    u8g2.setFont(u8g2_font_5x7_tr);
    u8g2.drawStr(3, 9, "# PC CONTROL");

    // OutsideFrame
    u8g2.drawXBMP(3, 11, 123, 50, image_OutsideFrame_bits);

    // Layer 6
    u8g2.setFont(u8g2_font_profont12_tr);
    u8g2.drawStr(8, 24, AppNames[(currentAppIndex - 1 + totalApps) % totalApps][0]);

    // Layer 5
    u8g2.setFont(u8g2_font_t0_15b_tr);
    u8g2.drawStr(8, 41, AppNames[currentAppIndex][0]);

    // Layer 7
    u8g2.setFont(u8g2_font_profont12_tr);
    u8g2.drawStr(8, 57, AppNames[(currentAppIndex + 1) % totalApps][0]);

    // Layer 8
    u8g2.setDrawColor(2);
    u8g2.drawBox(4, 27, 121, 19);

    u8g2.setDrawColor(2);
    u8g2.drawXBMP(115, 34, 7, 5, image_Arrow_bits);

    u8g2.sendBuffer();
}
